LEGACY_OBSERVATION = '{"values": {"Task Time Required": "Worker", "A": "", "B": "", "C": "", "D": "", "E": "", "F": "", "G": "", "H": "", "I": "", "J": ""}}\n{"values": {"Task Time Required": "1", "A": "9", "B": "4", "C": "3", "D": "7", "E": "6", "F": "5", "G": "6", "H": "3", "I": "7", "J": "5"}}\n{"values": {"Task Time Required": "2", "A": "4", "B": "6", "C": "5", "D": "6", "E": "4", "F": "5", "G": "3", "H": "8", "I": "7", "J": "6"}}\n{"values": {"Task Time Required": "3", "A": "5", "B": "4", "C": "7", "D": "5", "E": "6", "F": "6", "G": "5", "H": "8", "I": "6", "J": "9"}}\n{"values": {"Task Time Required": "4", "A": "7", "B": "5", "C": "2", "D": "3", "E": "7", "F": "8", "G": "5", "H": "6", "I": "8", "J": "5"}}\n{"values": {"Task Time Required": "5", "A": "10", "B": "6", "C": "7", "D": "4", "E": "5", "F": "4", "G": "4", "H": "5", "I": "9", "J": "7"}}\n{"values": {"Task Time Required": "6", "A": "6", "B": "7", "C": "6", "D": "3", "E": "9", "F": "5", "G": "7", "H": "4", "I": "3", "J": "4"}}\n{"values": {"Task Time Required": "7", "A": "8", "B": "8", "C": "5", "D": "9", "E": "5", "F": "7", "G": "5", "H": "9", "I": "5", "J": "3"}}\n{"values": {"Task Time Required": "8", "A": "7", "B": "4", "C": "8", "D": "8", "E": "6", "F": "7", "G": "5", "H": "7", "I": "7", "J": "7"}}\n{"values": {"Task Time Required": "9", "A": "5", "B": "6", "C": "8", "D": "7", "E": "7", "F": "8", "G": "7", "H": "8", "I": "4", "J": "5"}}\n{"values": {"Task Time Required": "10", "A": "8", "B": "7", "C": "9", "D": "5", "E": "8", "F": "5", "G": "9", "H": "9", "I": "3", "J": "4"}}\n{"values": {"Task Time Required": "11", "A": "9", "B": "8", "C": "10", "D": "8", "E": "5", "F": "4", "G": "7", "H": "6", "I": "8", "J": "7"}}\n{"values": {"Task Time Required": "12", "A": "8", "B": "5", "C": "6", "D": "9", "E": "4", "F": "7", "G": "8", "H": "4", "I": "7", "J": "9"}}'
LEGACY_RECORDS = [{'source': '', 'values': {'Task Time Required': 'Worker', 'A': '', 'B': '', 'C': '', 'D': '', 'E': '', 'F': '', 'G': '', 'H': '', 'I': '', 'J': ''}}, {'source': '', 'values': {'Task Time Required': '1', 'A': '9', 'B': '4', 'C': '3', 'D': '7', 'E': '6', 'F': '5', 'G': '6', 'H': '3', 'I': '7', 'J': '5'}}, {'source': '', 'values': {'Task Time Required': '2', 'A': '4', 'B': '6', 'C': '5', 'D': '6', 'E': '4', 'F': '5', 'G': '3', 'H': '8', 'I': '7', 'J': '6'}}, {'source': '', 'values': {'Task Time Required': '3', 'A': '5', 'B': '4', 'C': '7', 'D': '5', 'E': '6', 'F': '6', 'G': '5', 'H': '8', 'I': '6', 'J': '9'}}, {'source': '', 'values': {'Task Time Required': '4', 'A': '7', 'B': '5', 'C': '2', 'D': '3', 'E': '7', 'F': '8', 'G': '5', 'H': '6', 'I': '8', 'J': '5'}}, {'source': '', 'values': {'Task Time Required': '5', 'A': '10', 'B': '6', 'C': '7', 'D': '4', 'E': '5', 'F': '4', 'G': '4', 'H': '5', 'I': '9', 'J': '7'}}, {'source': '', 'values': {'Task Time Required': '6', 'A': '6', 'B': '7', 'C': '6', 'D': '3', 'E': '9', 'F': '5', 'G': '7', 'H': '4', 'I': '3', 'J': '4'}}, {'source': '', 'values': {'Task Time Required': '7', 'A': '8', 'B': '8', 'C': '5', 'D': '9', 'E': '5', 'F': '7', 'G': '5', 'H': '9', 'I': '5', 'J': '3'}}, {'source': '', 'values': {'Task Time Required': '8', 'A': '7', 'B': '4', 'C': '8', 'D': '8', 'E': '6', 'F': '7', 'G': '5', 'H': '7', 'I': '7', 'J': '7'}}, {'source': '', 'values': {'Task Time Required': '9', 'A': '5', 'B': '6', 'C': '8', 'D': '7', 'E': '7', 'F': '8', 'G': '7', 'H': '8', 'I': '4', 'J': '5'}}, {'source': '', 'values': {'Task Time Required': '10', 'A': '8', 'B': '7', 'C': '9', 'D': '5', 'E': '8', 'F': '5', 'G': '9', 'H': '9', 'I': '3', 'J': '4'}}, {'source': '', 'values': {'Task Time Required': '11', 'A': '9', 'B': '8', 'C': '10', 'D': '8', 'E': '5', 'F': '4', 'G': '7', 'H': '6', 'I': '8', 'J': '7'}}, {'source': '', 'values': {'Task Time Required': '12', 'A': '8', 'B': '5', 'C': '6', 'D': '9', 'E': '4', 'F': '7', 'G': '8', 'H': '4', 'I': '7', 'J': '9'}}]
import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
header = None
for rec in records:
    if rec['values'].get('Task Time Required') == 'Worker':
        header = rec['values']
        break
if header is None:
    raise ValueError('Header row not found in LEGACY_RECORDS.')
tasks = [k for k in header.keys() if k not in ('Task Time Required', '')]
workers = []
c = {}
for rec in records:
    v = rec['values']
    wid = v.get('Task Time Required')
    if wid is None or wid == 'Worker':
        continue
    workers.append(wid)
    c[wid] = {}
    for t in tasks:
        sval = v.get(t)
        if sval is None or sval == '':
            raise ValueError(f'Missing time for worker {wid}, task {t}')
        c[wid][t] = int(sval)
if len(workers) != 12 or len(tasks) != 10:
    raise ValueError('Unexpected number of workers or tasks.')
m = gp.Model('worker_task_assignment')
x = m.addVars(workers, tasks, vtype=GRB.BINARY, name='')
y = m.addVars(workers, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((c[w][t] * x[w, t] for w in workers for t in tasks)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[w, t] for w in workers)) == 1 for t in tasks), name='')
m.addConstrs((gp.quicksum((x[w, t] for t in tasks)) <= y[w] for w in workers), name='')
m.addConstr(gp.quicksum((y[w] for w in workers)) == 10, name='select_10_workers')
m.addConstrs((gp.quicksum((x[w, t] for t in tasks)) >= y[w] for w in workers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')